import java.util.*;

public class Main {
    // Bubble: swap neighbours that are out of order; stop when a pass makes no swap.
    static int bubble(int[] a) {
        int swaps = 0;
        for (int end = a.length - 1; end > 0; end--) {
            boolean swapped = false;
            for (int i = 0; i < end; i++)
                if (a[i] > a[i + 1]) { int t = a[i]; a[i] = a[i + 1]; a[i + 1] = t; swaps++; swapped = true; }
            if (!swapped) break;
        }
        return swaps;
    }
    // Selection: find the smallest of the rest, then one swap per position.
    static int selection(int[] a) {
        int swaps = 0;
        for (int i = 0; i < a.length - 1; i++) {
            int m = i;
            for (int j = i + 1; j < a.length; j++) if (a[j] < a[m]) m = j;
            if (m != i) { int t = a[i]; a[i] = a[m]; a[m] = t; swaps++; }
        }
        return swaps;
    }
    // Insertion: shift bigger items one step right, drop the key into the gap.
    static int insertion(int[] a) {
        int shifts = 0;
        for (int i = 1; i < a.length; i++) {
            int key = a[i], j = i - 1;
            while (j >= 0 && a[j] > key) { a[j + 1] = a[j]; j--; shifts++; }
            a[j + 1] = key;
        }
        return shifts;
    }
    // All three: O(N^2) time in the worst case, O(1) extra space.
    public static void main(String[] args) {
        int[] input = {4, 5, 1, 2, 3};
        System.out.println("Input: " + Arrays.toString(input));
        int[] a = input.clone(), b = input.clone(), c = input.clone();
        int x = bubble(a), y = selection(b), z = insertion(c);
        System.out.println("Bubble swaps: " + x + " -> " + Arrays.toString(a));
        System.out.println("Selection swaps: " + y + " -> " + Arrays.toString(b));
        System.out.println("Insertion shifts: " + z + " -> " + Arrays.toString(c));
    }
}

