#include <bits/stdc++.h>
using namespace std;

// Bubble: swap neighbours that are out of order; stop when a pass makes no swap.
int bubbleSort(vector<int>& a) {
    int swaps = 0;
    for (int end = (int)a.size() - 1; end > 0; end--) {
        bool swapped = false;
        for (int i = 0; i < end; i++)
            if (a[i] > a[i + 1]) { swap(a[i], a[i + 1]); swaps++; swapped = true; }
        if (!swapped) break;
    }
    return swaps;
}
// Selection: find the smallest of the rest, then one swap per position.
int selectionSort(vector<int>& a) {
    int swaps = 0, n = a.size();
    for (int i = 0; i < n - 1; i++) {
        int m = i;
        for (int j = i + 1; j < n; j++) if (a[j] < a[m]) m = j;
        if (m != i) { swap(a[i], a[m]); swaps++; }
    }
    return swaps;
}
// Insertion: shift bigger items one step right, drop the key into the gap.
int insertionSort(vector<int>& a) {
    int shifts = 0;
    for (int i = 1; i < (int)a.size(); i++) {
        int key = a[i], j = i - 1;
        while (j >= 0 && a[j] > key) { a[j + 1] = a[j]; j--; shifts++; }
        a[j + 1] = key;
    }
    return shifts;
}
string show(const vector<int>& a) {
    string s = "[";
    for (size_t i = 0; i < a.size(); i++) s += (i ? ", " : "") + to_string(a[i]);
    return s + "]";
}
// All three: O(N^2) time in the worst case, O(1) extra space.
int main() {
    vector<int> input = {4, 5, 1, 2, 3};
    cout << "Input: " << show(input) << "\n";
    vector<int> a = input, b = input, c = input;
    int x = bubbleSort(a), y = selectionSort(b), z = insertionSort(c);
    cout << "Bubble swaps: " << x << " -> " << show(a) << "\n";
    cout << "Selection swaps: " << y << " -> " << show(b) << "\n";
    cout << "Insertion shifts: " << z << " -> " << show(c) << "\n";
}

