import java.util.*;

public class Main {
    // One stable counting sort on the digit at place exp (1, 10, 100, ...).
    static void countingPass(int[] a, int exp) {
        int n = a.length;
        int[] out = new int[n];
        int[] count = new int[10];
        for (int x : a) count[(x / exp) % 10]++;               // how many of each digit
        for (int d = 1; d < 10; d++) count[d] += count[d - 1]; // prefix sums = end positions
        for (int i = n - 1; i >= 0; i--) {                     // right to left keeps it stable
            int d = (a[i] / exp) % 10;
            out[--count[d]] = a[i];
        }
        System.arraycopy(out, 0, a, 0, n);
    }

    public static void main(String[] args) {
        int[] a = {170, 45, 75, 90, 802, 24, 2, 66};
        System.out.println("Input: " + Arrays.toString(a));
        int max = 0;
        for (int x : a) max = Math.max(max, x);
        // Least significant digit first. Time O(d * (N + 10)), space O(N + 10).
        for (int exp = 1; max / exp > 0; exp *= 10) {
            countingPass(a, exp);
            System.out.println("After place " + exp + ": " + Arrays.toString(a));
        }
    }
}

