import java.util.*;

public class Main {
    // Merge two sorted parts a[lo..mid] and a[mid+1..hi] using a temp buffer.
    static void merge(int[] a, int[] tmp, int lo, int mid, int hi) {
        int i = lo, j = mid + 1, k = lo;
        while (i <= mid && j <= hi)
            tmp[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];   // <= takes the left on ties: stable
        while (i <= mid) tmp[k++] = a[i++];
        while (j <= hi) tmp[k++] = a[j++];
        for (k = lo; k <= hi; k++) a[k] = tmp[k];
    }

    static void mergeSort(int[] a, int[] tmp, int lo, int hi) {
        if (lo >= hi) return;                  // 0 or 1 item is already sorted
        int mid = lo + (hi - lo) / 2;
        mergeSort(a, tmp, lo, mid);            // sort the left half
        mergeSort(a, tmp, mid + 1, hi);        // sort the right half
        merge(a, tmp, lo, mid, hi);            // join them in O(hi - lo) time
    }

    public static void main(String[] args) {
        int[] a = {38, 27, 43, 3, 9, 82, 10};
        System.out.println("Input:  " + Arrays.toString(a));
        // Time O(N log N) in every case, space O(N) buffer + O(log N) stack.
        mergeSort(a, new int[a.length], 0, a.length - 1);
        System.out.println("Sorted: " + Arrays.toString(a));
    }
}

