import java.util.*;

public class Main {
    // Sorts a[lo..hi] and returns how many inversions it contained.
    static long sortCount(int[] a, int[] tmp, int lo, int hi) {
        if (lo >= hi) return 0;
        int mid = lo + (hi - lo) / 2;
        long count = sortCount(a, tmp, lo, mid) + sortCount(a, tmp, mid + 1, hi);
        int i = lo, j = mid + 1, k = lo;
        while (i <= mid && j <= hi) {
            if (a[i] <= a[j]) {
                tmp[k++] = a[i++];            // equal values are not inversions
            } else {
                tmp[k++] = a[j++];
                count += mid - i + 1;         // a[j] beats every item left in the left half
            }
        }
        while (i <= mid) tmp[k++] = a[i++];
        while (j <= hi) tmp[k++] = a[j++];
        for (k = lo; k <= hi; k++) a[k] = tmp[k];
        return count;
    }

    public static void main(String[] args) {
        int[] a = {5, 3, 2, 4, 1};
        System.out.println("Input: " + Arrays.toString(a));
        // Time O(N log N), space O(N). long because the count can reach N(N-1)/2.
        long inv = sortCount(a, new int[a.length], 0, a.length - 1);
        System.out.println("Inversions: " + inv);
        System.out.println("Sorted: " + Arrays.toString(a));
    }
}

