import java.util.*;

public class Main {
    static int swaps;
    static void swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; swaps++; }

    // Lomuto: pivot = last item; a[lo..i-1] is the "smaller than pivot" zone.
    static int lomuto(int[] a, int lo, int hi) {
        int p = a[hi], i = lo;
        for (int j = lo; j < hi; j++)
            if (a[j] < p) swap(a, i++, j);
        swap(a, i, hi);                 // the pivot lands at its final index i
        return i;
    }

    // Hoare: two pointers walk inwards and swap items that sit on the wrong side.
    static int hoare(int[] a, int lo, int hi) {
        int p = a[lo + (hi - lo) / 2];  // lower middle pivot avoids endless recursion
        int i = lo - 1, j = hi + 1;
        while (true) {
            do { i++; } while (a[i] < p);
            do { j--; } while (a[j] > p);
            if (i >= j) return j;       // a[lo..j] <= p <= a[j+1..hi]
            swap(a, i, j);
        }
    }

    // Both run in O(N) time and O(1) space.
    public static void main(String[] args) {
        int[] input = {3, 8, 2, 5, 1, 4, 7, 6};
        System.out.println("Input:  " + Arrays.toString(input));
        int[] a = input.clone();
        swaps = 0;
        int p = lomuto(a, 0, a.length - 1);
        System.out.println("Lomuto: " + Arrays.toString(a) + " pivot index " + p + ", swaps " + swaps);
        int[] b = input.clone();
        swaps = 0;
        int q = hoare(b, 0, b.length - 1);
        System.out.println("Hoare:  " + Arrays.toString(b) + " split after index " + q + ", swaps " + swaps);
    }
}

