public class Main {
    static long comparisons;
    static int maxDepth;

    // Index of the middle value among a[x], a[y], a[z].
    static int medianIndex(int[] a, int x, int y, int z) {
        if ((a[x] <= a[y]) == (a[y] <= a[z])) return y;
        if ((a[y] <= a[x]) == (a[x] <= a[z])) return x;
        return z;
    }

    static void quickSort(int[] a, int lo, int hi, boolean medianOfThree, int depth) {
        if (lo >= hi) return;
        maxDepth = Math.max(maxDepth, depth);
        if (medianOfThree) {                       // move a better pivot to the end
            int m = medianIndex(a, lo, lo + (hi - lo) / 2, hi);
            int t = a[m]; a[m] = a[hi]; a[hi] = t;
        }
        int p = a[hi], i = lo;                     // Lomuto partition
        for (int j = lo; j < hi; j++) {
            comparisons++;
            if (a[j] < p) { int t = a[i]; a[i] = a[j]; a[j] = t; i++; }
        }
        int t = a[i]; a[i] = a[hi]; a[hi] = t;
        quickSort(a, lo, i - 1, medianOfThree, depth + 1);
        quickSort(a, i + 1, hi, medianOfThree, depth + 1);
    }

    static void run(String label, boolean medianOfThree) {
        int n = 100;
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = i + 1;  // already sorted: the classic bad case
        comparisons = 0; maxDepth = 0;
        quickSort(a, 0, n - 1, medianOfThree, 1);
        System.out.println(label + ": comparisons = " + comparisons + ", recursion depth = " + maxDepth);
    }

    // Bad pivots: O(N^2) time, O(N) stack. Good pivots: O(N log N) time, O(log N) stack.
    public static void main(String[] args) {
        System.out.println("Input: 1, 2, ..., 100 (already sorted)");
        run("Last-element pivot", false);
        run("Median-of-three pivot", true);
    }
}

