import java.util.*;

public class Main {
    // Returns the value that would be at index target if a were sorted.
    static int quickselect(int[] a, int target) {
        int lo = 0, hi = a.length - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            int t = a[mid]; a[mid] = a[hi]; a[hi] = t;     // middle item as pivot
            int p = a[hi], i = lo;
            for (int j = lo; j < hi; j++)
                if (a[j] < p) { t = a[i]; a[i] = a[j]; a[j] = t; i++; }
            t = a[i]; a[i] = a[hi]; a[hi] = t;             // pivot is now at its final index i
            if (i == target) return a[i];
            if (i < target) lo = i + 1; else hi = i - 1;   // keep only the side holding target
        }
        return a[lo];
    }

    public static void main(String[] args) {
        int[] input = {7, 2, 9, 4, 1, 8, 5};
        int k = 3;
        System.out.println("Input: " + Arrays.toString(input) + ", k = " + k);
        // Way 1: sort everything. O(N log N).
        int[] sorted = input.clone();
        Arrays.sort(sorted);
        System.out.println("Sorted: " + Arrays.toString(sorted));
        System.out.println("By sorting: " + sorted[sorted.length - k]);
        // Way 2: quickselect. Expected O(N) time, O(1) space; the k-th largest is index N - k.
        int[] work = input.clone();
        System.out.println("By quickselect: " + quickselect(work, work.length - k));
    }
}

