import java.util.*;

public class Main {
    public static void main(String[] args) {
        String[] names = {"Ravi", "Anu", "Meera", "Dev", "Bala"};
        int[] scores = {90, 85, 90, 70, 85};
        System.out.println("Input:");
        for (int i = 0; i < names.length; i++) System.out.println("  " + names[i] + " " + scores[i]);

        // int[] cannot take a comparator, so sort boxed positions 0..N-1 instead.
        Integer[] order = new Integer[names.length];
        for (int i = 0; i < order.length; i++) order[i] = i;

        // Negative result = x goes first, positive = y goes first, 0 = tie.
        Arrays.sort(order, (x, y) -> {
            if (scores[x] != scores[y])
                return Integer.compare(scores[y], scores[x]);  // y before x gives high to low
            return names[x].compareTo(names[y]);               // tie: name A to Z
        });
        // Integer.compare is safe; "scores[y] - scores[x]" can overflow for big values.

        // Time O(N log N) comparisons, space O(N) for the order array.
        System.out.println("Sorted by score (high to low), then name:");
        for (int i : order) System.out.println("  " + names[i] + " " + scores[i]);
    }
}

