    for (size_t i = 0; i < names.size(); i++) cout << "  " << names[i] << " " << scores[i] << "\n";

    // Sort the positions 0..N-1 so both vectors stay untouched.
    vector<int> order(names.size());
    iota(order.begin(), order.end(), 0);

    // A C++ comparator answers one question: must x come before y? (true or false)
    sort(order.begin(), order.end(), [&](int x, int y) {
        if (scores[x] != scores[y]) return scores[x] > scores[y];  // high to low
        return names[x] < names[y];                                // tie: name A to Z
    });
    // It must return false for equal items; using >= or <= here is undefined behaviour.

    // Time O(N log N) comparisons, space O(N) for the order vector.
    cout << "Sorted by score (high to low), then name:\n";
    for (int i : order) cout << "  " << names[i] << " " << scores[i] << "\n";
}

