        Array.Sort(order, (x, y) => {
            if (scores[x] != scores[y])
                return scores[y].CompareTo(scores[x]);         // y before x gives high to low
            return string.CompareOrdinal(names[x], names[y]);  // tie: name A to Z
        });
        // CompareTo is safe; "scores[y] - scores[x]" can overflow for big values.

        // Time O(N log N) comparisons, space O(N) for the order array.
        Console.WriteLine("Sorted by score (high to low), then name:");
        foreach (int i in order) Console.WriteLine("  " + names[i] + " " + scores[i]);
    }
}

