public class Main {
    // Insertion sort of positions by key. Stable: strict > never moves an item past an equal key.
    static int[] insertionOrder(int[] key) {
        int n = key.length;
        int[] ord = new int[n];
        for (int i = 0; i < n; i++) ord[i] = i;
        for (int i = 1; i < n; i++) {
            int cur = ord[i], j = i - 1;
            while (j >= 0 && key[ord[j]] > key[cur]) { ord[j + 1] = ord[j]; j--; }
            ord[j + 1] = cur;
        }
        return ord;
    }

    // Selection sort of positions by key. Unstable: the long swap can jump over an equal key.
    static int[] selectionOrder(int[] key) {
        int n = key.length;
        int[] ord = new int[n];
        for (int i = 0; i < n; i++) ord[i] = i;
        for (int i = 0; i < n - 1; i++) {
            int m = i;
            for (int j = i + 1; j < n; j++) if (key[ord[j]] < key[ord[m]]) m = j;
            int t = ord[i]; ord[i] = ord[m]; ord[m] = t;
        }
        return ord;
    }

    static String show(String[] names, int[] key, int[] ord) {
        StringBuilder sb = new StringBuilder();
        for (int i : ord) sb.append(sb.length() > 0 ? " " : "").append(names[i]).append(":").append(key[i]);
        return sb.toString();
    }

    // Both sorts are O(N^2) time and O(1) extra space besides the order array.
    public static void main(String[] args) {
        String[] names = {"Asha", "Bina", "Chen"};
        int[] grade = {2, 2, 1};
        System.out.println("Input:                " + show(names, grade, new int[]{0, 1, 2}));
        System.out.println("Insertion (stable):   " + show(names, grade, insertionOrder(grade)));
        System.out.println("Selection (unstable): " + show(names, grade, selectionOrder(grade)));
        System.out.println("Asha and Bina both have grade 2; only the stable sort keeps Asha first.");
    }
}

