def insertion_order(key):
    order = list(range(len(key)))
    for i in range(1, len(order)):
        cur, j = order[i], i - 1
        while j >= 0 and key[order[j]] > key[cur]:
            order[j + 1] = order[j]
            j -= 1
        order[j + 1] = cur
    return order

