vector<int> insertionOrder(const vector<int>& key) {
    int n = key.size();
    vector<int> ord(n);
    iota(ord.begin(), ord.end(), 0);
    for (int i = 1; i < n; i++) {
        int cur = ord[i], j = i - 1;
        while (j >= 0 && key[ord[j]] > key[cur]) { ord[j + 1] = ord[j]; j--; }
        ord[j + 1] = cur;
    }
    return ord;
