    int n = key.size();
    vector<int> ord(n);
    iota(ord.begin(), ord.end(), 0);
    for (int i = 0; i < n - 1; i++) {
        int m = i;
        for (int j = i + 1; j < n; j++) if (key[ord[j]] < key[ord[m]]) m = j;
