import java.util.*;

public class Main {
    static List<int[]> merge(int[][] intervals) {
        int[][] iv = new int[intervals.length][];
        for (int i = 0; i < iv.length; i++) iv[i] = intervals[i].clone();  // do not change the input
        Arrays.sort(iv, (x, y) -> Integer.compare(x[0], y[0]));            // sort by start
        List<int[]> out = new ArrayList<>();
        for (int[] cur : iv) {
            int[] last = out.isEmpty() ? null : out.get(out.size() - 1);
            if (last != null && cur[0] <= last[1])
                last[1] = Math.max(last[1], cur[1]);   // overlap: extend; max handles nested ones
            else
                out.add(cur);                          // gap: start a new block
        }
        return out;
    }

    static String show(List<int[]> v) { return Arrays.deepToString(v.toArray(new int[0][])); }

    public static void main(String[] args) {
        int[][] intervals = {{1, 3}, {8, 10}, {2, 6}, {15, 18}, {9, 12}, {4, 5}};
        System.out.println("Input:  " + Arrays.deepToString(intervals));
        // Time O(N log N) for the sort, O(N) for the sweep; space O(N) for the output.
        System.out.println("Merged: " + show(merge(intervals)));
    }
}

