import java.util.*;

public class Main {
    static List<int[]> insert(int[][] iv, int[] add) {
        List<int[]> out = new ArrayList<>();
        int s = add[0], e = add[1], i = 0, n = iv.length;
        // Phase 1: intervals that end before the new one starts are copied unchanged.
        while (i < n && iv[i][1] < s) out.add(iv[i++]);
        // Phase 2: every interval that starts at or before e overlaps; absorb it.
        while (i < n && iv[i][0] <= e) {
            s = Math.min(s, iv[i][0]);
            e = Math.max(e, iv[i][1]);
            i++;
        }
        out.add(new int[]{s, e});                 // add the fused interval once
        // Phase 3: the rest start after e; copy them unchanged.
        while (i < n) out.add(iv[i++]);
        return out;
    }

    static String show(List<int[]> v) { return Arrays.deepToString(v.toArray(new int[0][])); }

    public static void main(String[] args) {
        int[][] iv = {{1, 2}, {3, 5}, {6, 7}, {8, 10}, {12, 16}};
        int[] add = {4, 8};
        System.out.println("Intervals: " + Arrays.deepToString(iv));
        System.out.println("Insert:    " + Arrays.toString(add));
        // Time O(N), space O(N) for the output. No sorting is needed.
        System.out.println("Result:    " + show(insert(iv, add)));
    }
}

