using System;
using System.Collections.Generic;

class Program {
    static int MinRooms(int[][] meetings) {
        int n = meetings.Length;
        int[] starts = new int[n], ends = new int[n];
        for (int i = 0; i < n; i++) { starts[i] = meetings[i][0]; ends[i] = meetings[i][1]; }
        Array.Sort(starts);                  // the two lists are sorted separately
        Array.Sort(ends);
        int rooms = 0, j = 0;                // j points at the earliest end not yet used
        for (int i = 0; i < n; i++) {
            if (starts[i] >= ends[j]) j++;   // a meeting has finished: reuse its room
            else rooms++;                    // every room is busy: open a new one
        }
        return rooms;
    }

    static string Show(int[][] v) {
        List<string> parts = new List<string>();
        foreach (int[] x in v) parts.Add("[" + x[0] + ", " + x[1] + "]");
        return "[" + string.Join(", ", parts) + "]";
    }

    static void Main() {
        int[][] meetings = {
            new int[] {0, 30}, new int[] {5, 10}, new int[] {15, 20}, new int[] {10, 25}
        };
        Console.WriteLine("Meetings: " + Show(meetings));
        // Time O(N log N) for the two sorts, space O(N).
        // >= means a meeting ending at 10 frees its room for one starting at 10.
        Console.WriteLine("Rooms needed: " + MinRooms(meetings));
    }
}

