import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] a = {1, 2, 3, 7, 6, 5, 4, 8, 9, 2};
        System.out.println("Input: " + Arrays.toString(a));
        // Part 1: find "runs" the way TimSort does: stretches that are already
        // non-decreasing, or strictly decreasing (those it simply reverses).
        int i = 0, runs = 0, n = a.length;
        while (i < n) {
            int j = i + 1;
            boolean down = j < n && a[j] < a[i];
            if (down) while (j < n && a[j] < a[j - 1]) j++;
            else while (j < n && a[j] >= a[j - 1]) j++;
            runs++;
            System.out.println("Run " + runs + ": index " + i + ".." + (j - 1)
                    + (down ? " descending" : " ascending") + ", length " + (j - i));
            i = j;                           // the next run starts where this one ended
        }
        // Finding runs is one O(N) pass; sorted input is a single run, so TimSort is O(N) on it.

        // Part 2: the object sort (TimSort) is stable: equal lengths keep their input order.
        String[] words = {"pear", "fig", "apple", "kiwi", "plum", "date"};
        System.out.println("Words: " + String.join(" ", words));
        Arrays.sort(words, Comparator.comparingInt(String::length));   // O(N log N), stable
        System.out.println("By length (stable): " + String.join(" ", words));
    }
}

