    cout << "Input: [";
    for (size_t k = 0; k < a.size(); k++) cout << (k ? ", " : "") << a[k];
    cout << "]\n";
    // Part 1: find "runs" the way TimSort does: stretches that are already
    // non-decreasing, or strictly decreasing (those it simply reverses).
    int i = 0, runs = 0, n = a.size();
    while (i < n) {
        int j = i + 1;
        bool down = j < n && a[j] < a[i];
        if (down) { while (j < n && a[j] < a[j - 1]) j++; }
        else { while (j < n && a[j] >= a[j - 1]) j++; }
        runs++;
        cout << "Run " << runs << ": index " << i << ".." << (j - 1)
             << (down ? " descending" : " ascending") << ", length " << (j - i) << "\n";
        i = j;                           // the next run starts where this one ended
    }
    // Finding runs is one O(N) pass; sorted input is a single run, so TimSort is O(N) on it.

    // Part 2: std::sort is not stable; std::stable_sort (a merge sort) keeps equal items in order.
    vector<string> words = {"pear", "fig", "apple", "kiwi", "plum", "date"};
    cout << "Words: " << joinWords(words) << "\n";
    stable_sort(words.begin(), words.end(), [](const string& x, const string& y) {
        return x.size() < y.size();      // O(N log N), stable
    });
    cout << "By length (stable): " << joinWords(words) << "\n";
}

