import java.util.*;

public class Main {
    // Sort by column key (0 = start, 1 = end), then keep every interval
    // that starts at or after the end of the last one kept.
    static List<int[]> pick(int[][] intervals, int key) {
        int[][] iv = intervals.clone();
        Arrays.sort(iv, (x, y) -> Integer.compare(x[key], y[key]));
        List<int[]> kept = new ArrayList<>();
        int lastEnd = Integer.MIN_VALUE;
        for (int[] cur : iv) {
            if (cur[0] >= lastEnd) {         // no clash with what we already kept
                kept.add(cur);
                lastEnd = cur[1];
            }
        }
        return kept;
    }

    static String show(List<int[]> v) { return Arrays.deepToString(v.toArray(new int[0][])); }

    public static void main(String[] args) {
        int[][] intervals = {{1, 10}, {2, 3}, {4, 5}, {6, 7}};
        System.out.println("Intervals: " + Arrays.deepToString(intervals));
        // Each run is O(N log N) time and O(N) space; only the sort key differs.
        List<int[]> byStart = pick(intervals, 0);
        List<int[]> byEnd = pick(intervals, 1);
        // Sorting by start grabs the long [1, 10] first and blocks everything else.
        System.out.println("Sort by start: kept " + byStart.size() + " -> " + show(byStart));
        // Sorting by end always keeps the interval that finishes first: the best choice.
        System.out.println("Sort by end:   kept " + byEnd.size() + " -> " + show(byEnd));
    }
}

