using System;
using System.Collections.Generic;

class Program {
    // Sort by column key (0 = start, 1 = end), then keep every interval
    // that starts at or after the end of the last one kept.
    static List<int[]> Pick(int[][] intervals, int key) {
        int[][] iv = (int[][])intervals.Clone();
        Array.Sort(iv, (x, y) => x[key].CompareTo(y[key]));
        List<int[]> kept = new List<int[]>();
        int lastEnd = int.MinValue;
        foreach (int[] cur in iv) {
            if (cur[0] >= lastEnd) {         // no clash with what we already kept
                kept.Add(cur);
                lastEnd = cur[1];
            }
        }
        return kept;
    }

    static string Show(IEnumerable<int[]> v) {
        List<string> parts = new List<string>();
        foreach (int[] x in v) parts.Add("[" + x[0] + ", " + x[1] + "]");
        return "[" + string.Join(", ", parts) + "]";
    }

    static void Main() {
        int[][] intervals = {
            new int[] {1, 10}, new int[] {2, 3}, new int[] {4, 5}, new int[] {6, 7}
        };
        Console.WriteLine("Intervals: " + Show(intervals));
        // Each run is O(N log N) time and O(N) space; only the sort key differs.
        List<int[]> byStart = Pick(intervals, 0);
        List<int[]> byEnd = Pick(intervals, 1);
        // Sorting by start grabs the long [1, 10] first and blocks everything else.
        Console.WriteLine("Sort by start: kept " + byStart.Count + " -> " + Show(byStart));
        // Sorting by end always keeps the interval that finishes first: the best choice.
        Console.WriteLine("Sort by end:   kept " + byEnd.Count + " -> " + Show(byEnd));
    }
}
